For a free particle with $m, c > 0$,
\begin{align}
E &= \sqrt{p^2 c^2 + m^2 c^4} \\
  &= m c^2 \sqrt{1 + \frac{p^2}{m^2 c^2}} .
\end{align}
Expanding for small $p$, to second order in $p$,
\begin{equation}
E \approx m c^2 + \frac{p^2}{2m} .
\end{equation}

For a free particle with $m, c > 0$,
\begin{equation}
E = m c^2 \sqrt{1 + \frac{p^2}{m^2 c^2}} .
\end{equation}
Expanding for small $p$, to second order in $p$,
\begin{equation}
E \approx m c^2 + \frac{p^2}{m} .
\end{equation}

Take $x = A\cos(\omega t + \phi)$ and $v = -A\omega\sin(\omega t + \phi)$, with
$\omega = \sqrt{k/m}$ and $k, m > 0$. Then
\begin{align}
E &= \frac{1}{2} m v^2 + \frac{1}{2} k x^2 \\
  &= \frac{1}{2} k A^2 .
\end{align}

With $p = \hbar k$ and $\hbar, m > 0$,
\begin{align}
E &= \frac{p^2}{2m} \\
  &= \frac{\hbar^2 k^2}{m} .
\end{align}

The Gaussian integral is
\begin{equation}
\int_{-\infty}^{\infty} e^{-x^2} dx = \sqrt{\pi} .
\end{equation}

Expanding the square,
\begin{equation}
(a + b)^2 = a^2 + b^2 .
\end{equation}

With $\omega_c = \frac{e B}{m}$ and $e, B, m, \hbar > 0$, the spacing between Landau levels is
\begin{align}
\Delta E &= \hbar\omega_c\left(n + 1 + \frac{1}{2}\right) - \hbar\omega_c\left(n + \frac{1}{2}\right) \\
         &= \frac{\hbar e B}{m} .
\end{align}

Near the Dirac point of graphene, with $t, a, \hbar > 0$ and $v_F = \frac{3 t a}{2\hbar}$,
\begin{align}
E &= \hbar v_F q \\
  &= \frac{3 t a}{\hbar} \hbar q .
\end{align}
